#pragma once
#include <string>
#include <fstream>
#include <stdexcept>
class INIReader;
class INIWriter {
public:
    INIWriter() = default;

    inline static void write(const std::string& filepath, const INIReader& reader, const bool overwrite = false) {
        if (!overwrite && std::ifstream(filepath)) {
            throw std::runtime_error("File already exists and overwrite is false.");
        }
        std::ofstream file(filepath);
        if (!file.is_open()) {
            throw std::runtime_error("Failed to open the output file.");
        }
        for (const auto& section : reader.getSections()) {
            file << "[" << section.first << "]\n";
            for (const auto& key_value : section.second) {
                file << key_value.first << "=" << key_value.second << "\n";
            }
        }
    }
};
